// Deixa o nome do condomínio com cara de escrito por gente: "CONDOMINIO RESIDENCIAL SAO JOAO" -> "Condomínio Residencial São João".
const acentos = { CONDOMINIO: 'Condomínio', EDIFICIO: 'Edifício', RESIDENCIA: 'Residência', MANSAO: 'Mansão', SAO: 'São', JOAO: 'João', JOSE: 'José', CONCEICAO: 'Conceição', ESTACAO: 'Estação', PRACA: 'Praça', ATLANTICO: 'Atlântico', MARITIMO: 'Marítimo', VITORIA: 'Vitória', GUANABARA: 'Guanabara' };
const pequenas = new Set(['DE','DA','DO','DAS','DOS','E','EM']);
let bruto = String($json.nome_bruto || '').replace(/\s+(LTDA|ME|EPP|EIRELI)\.?$/i, '').trim();
const nome = bruto.split(/\s+/).filter(Boolean).map((p, i) => {
  const up = p.toUpperCase();
  if (acentos[up]) return acentos[up];
  if (i > 0 && pequenas.has(up)) return p.toLowerCase();
  if (/^[IVX]+$/.test(up)) return up;
  return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
}).join(' ') || 'condomínio';

const textos = {
  inicial: 'Oi, tudo bem? Aqui é do escritório Monteiro Ramalho Advogados. Você é o síndico do ' + nome + '? Queria trocar uma ideia rápida sobre o condomínio, pode ser por aqui?',
  fu1: 'Oi, tudo bem? Passando de novo por aqui, do escritório Monteiro Ramalho. Consegue me dizer se você é o síndico do ' + nome + '? Fico no aguardo.',
  fu2: 'Oi! Última mensagem por aqui, prometo. Se fizer sentido conversar sobre o ' + nome + ' em algum momento, é só me chamar. Abraço!',
};
return { json: { ...$json, nome, texto: textos[$json.acao] } };

const p = $('Prepara a mensagem').item.json;
const msgId = $json.messages && $json.messages[0] ? $json.messages[0].id : null;
const erro = msgId ? null : JSON.stringify($json.error || $json).slice(0, 500);
return { json: { id: p.id, acao: p.acao, ok: !!msgId, erro, texto: p.texto, telefone: p.telefone_normalizado, message_id: msgId } };
